class Solution {
    public int networkDelayTime(int[][] times, int n, int k) {
        int inf = 1_000_000_000;
        int[][] dist = new int[n + 1][n + 1];
        for (int i = 1; i <= n; i++) {
            Arrays.fill(dist[i], inf);
            dist[i][i] = 0;
        }
        for (int[] edge : times) {
            dist[edge[0]][edge[1]] = edge[2];
        }

        for (int mid = 1; mid <= n; mid++) {
            for (int from = 1; from <= n; from++) {
                if (dist[from][mid] == inf) {
                    continue;
                }
                for (int to = 1; to <= n; to++) {
                    if (dist[mid][to] != inf && dist[from][mid] + dist[mid][to] < dist[from][to]) {
                        dist[from][to] = dist[from][mid] + dist[mid][to];
                    }
                }
            }
        }

        int answer = 0;
        for (int node = 1; node <= n; node++) {
            if (dist[k][node] == inf) {
                return -1;
            }
            answer = Math.max(answer, dist[k][node]);
        }
        return answer;
    }
}

import java.util.*;

class Solution {
    public int networkDelayTime(int[][] times, int n, int k) {
        List<List<int[]>> graph = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            graph.add(new ArrayList<>());
        }
        for (int[] edge : times) {
            graph.get(edge[0]).add(new int[]{edge[1], edge[2]});
        }

        int inf = 1_000_000_000;
        int[] dist = new int[n + 1];
        Arrays.fill(dist, inf);
        dist[k] = 0;

        Queue<Integer> queue = new ArrayDeque<>();
        boolean[] inQueue = new boolean[n + 1];
        queue.offer(k);
        inQueue[k] = true;

        while (!queue.isEmpty()) {
            int node = queue.poll();
            inQueue[node] = false;
            for (int[] edge : graph.get(node)) {
                int next = edge[0];
                int arrival = dist[node] + edge[1];
                if (arrival < dist[next]) {
                    dist[next] = arrival;
                    if (!inQueue[next]) {
                        queue.offer(next);
                        inQueue[next] = true;
                    }
                }
            }
        }

        int answer = 0;
        for (int node = 1; node <= n; node++) {
            if (dist[node] == inf) {
                return -1;
            }
            answer = Math.max(answer, dist[node]);
        }
        return answer;
    }
}
